# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def get_lang_code() -> str:
    """Return the ISO-639 code for the currently active language."""
    lang_name = st.session_state.get("settings", {}).get("language", "العربية")
    return LANGUAGES.get(lang_name, "ar")


def is_rtl() -> bool:
    """True when the active language reads right-to-left."""
    lang_name = st.session_state.get("settings", {}).get("language", "العربية")
    return lang_name in RTL_LANGUAGES


def get_months() -> list[str]:
    """Return month names for the current language."""
    return MONTHS.get(get_lang_code(), MONTHS["en"])


def translate_en(en: str, ar: str = "") -> str:
    """Translate an English key into the active language with optional Arabic."""
    code = get_lang_code()
    if code == "ar":
        return ar or en
    if code == "en":
        return en
    entry = _TRANSLATIONS.get(en)
    if entry and code in entry:
        return entry[code]
    return en


def format_i18n(key: str, **kwargs) -> str:
    """Format a localized dynamic UI string."""
    code = get_lang_code()
    templates = _DYNAMIC_MESSAGES.get(key, {})
    template = templates.get(code) or templates.get("en") or ""
    if not template:
        return ""
    if key == "month_count" and code == "en":
        count = int(kwargs.get("count", 0) or 0)
        kwargs.setdefault("unit", "month" if count == 1 else "months")
    if key == "document_count" and code in {"ar", "en"}:
        count = int(kwargs.get("count", 0) or 0)
        if code == "ar":
            kwargs.setdefault("unit", "مستند" if count == 1 else "مستندات")
        else:
            kwargs.setdefault("unit", "document" if count == 1 else "documents")
    return template.format(**kwargs)


def dashboard_brief_copy(brief: dict, currency_view: str, *, spending_note_on_good: bool = False) -> tuple[str, str, str, str]:
    """Return localized message, detail, focus label, and support label."""
    status = "spending_high_positive" if spending_note_on_good else str(brief.get("status", "stable") or "stable")
    if status == "empty":
        message = translate_en("Add your first transaction", "إضافة أول حركة مالية")
    elif status == "spending_high_positive":
        message = translate_en("Financial position is under control", "الوضع المالي تحت السيطرة")
    elif status == "note_pattern":
        merchant_label = str(brief.get("merchant_label", "") or "")
        note_templates = {
            "ar": "{merchant} واضح في مصروفك",
            "en": "{merchant} stands out this month",
            "zh": "{merchant} 本月很突出",
            "ko": "이번 달 {merchant} 지출이 두드러집니다",
            "ja": "今月は {merchant} が目立っています",
            "id": "{merchant} menonjol bulan ini",
            "ms": "{merchant} menonjol bulan ini",
        }
        code = get_lang_code()
        message = (note_templates.get(code) or note_templates["en"]).format(merchant=merchant_label)
    else:
        message = translate_en(str(brief.get("message_en", "") or ""), str(brief.get("message_ar", "") or ""))

    code = get_lang_code()
    detail_templates = _BRIEF_DETAIL_TEMPLATES.get(status, _BRIEF_DETAIL_TEMPLATES["stable"])
    detail_template = detail_templates.get(code) or detail_templates.get("en", "")
    detail = detail_template.format(
        currency=currency_view,
        projected_net=float(brief.get("projected_net", brief.get("focus_value", 0.0)) or 0.0),
        net_delta=float(brief.get("net_delta", 0.0) or 0.0),
        follow_up_total=float(brief.get("follow_up_total", brief.get("support_value", 0.0)) or 0.0),
        merchant_label=str(brief.get("merchant_label", "") or ""),
        merchant_count=int(brief.get("merchant_count", 0) or 0),
        merchant_amount=float(brief.get("merchant_amount", 0.0) or 0.0),
    )

    focus_label = translate_en(str(brief.get("focus_label_en", "") or ""), str(brief.get("focus_label_ar", "") or ""))
    support_label = translate_en(str(brief.get("support_label_en", "") or ""), str(brief.get("support_label_ar", "") or ""))
    return message, detail, focus_label, support_label


def make_t() -> Callable[[str, str], str]:
    """Build a translator for the current session language.

    Returns a callable with the legacy ``t(ar, en)`` signature.
    For Arabic and English the positional arguments are returned directly.
    For all other languages the *en* text is looked up in ``_TRANSLATIONS``.
    """
    lang_name = st.session_state.get("settings", {}).get("language", "العربية")
    code = LANGUAGES.get(lang_name, "ar")

    if code == "ar":
        return lambda ar, en: ar
    if code == "en":
        return lambda ar, en: en

    def _translate(ar: str, en: str) -> str:
        entry = _TRANSLATIONS.get(en)
        if entry and code in entry:
            return entry[code]
        return en  # fallback to English

    return _translate
